// Batenrealisatie: dashboard over site/data/benefits.json (generated by scripts/build.mjs from src/benefits.mjs).
// A simulation over the business-case model, not a measurement; the page says so in its header.
(() => {
  const $ = (id) => document.getElementById(id);
  const COLORS = { case03: "#e20000", case02: "#242a38", case01: "#9a5b00", total: "#6c6c6c" };
  const SCENARIO_TEXT = {
    voorzichtig: "Voorzichtig: 70% van de baten, volle gebruik pas na 18 maanden.",
    verwacht: "Verwacht: de baten van het rekenmodel, volle gebruik na 12 maanden.",
    gunstig: "Gunstig: 115% van de baten, volle gebruik na 8 maanden.",
  };
  const eur = (n) => `${n < 0 ? "−" : ""}€${Math.round(Math.abs(n)).toLocaleString("nl-BE")}`;
  const int = (n) => Math.round(n).toLocaleString("nl-BE");
  const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const state = { sc: "verwacht", cs: "alle", month: 24 };
  let data = null;

  // ------------------------------------------------------------------ SVG helpers
  let W = 760, H = 280;
  const P = { l: 64, r: 14, t: 14, b: 32 };
  const size = (w, h) => { W = w; H = h; };
  function frame(minY, maxY, months) {
    const x = (m) => P.l + (m / (months - 1)) * (W - P.l - P.r);
    const y = (v) => P.t + (1 - (v - minY) / (maxY - minY || 1)) * (H - P.t - P.b);
    return { x, y };
  }
  function niceTicks(min, max, n = 5) {
    const span = max - min || 1;
    const step = 10 ** Math.floor(Math.log10(span / n));
    const err = (span / n) / step;
    const s = step * (err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1);
    const out = [];
    // first tick at or below the minimum, last at or above the maximum: the data always fits the frame
    for (let v = Math.floor(min / s) * s; v < max + s - 1e-9; v += s) out.push(Math.round(v * 1e6) / 1e6);
    return out;
  }
  const short = (v, unit) => unit === "€" ? (Math.abs(v) >= 1000 ? `${v < 0 ? "−" : ""}€${Math.round(Math.abs(v) / 1000)}k` : eur(v)) : int(v);
  function axes(f, ticks, months, unit) {
    const g = ticks.map((t) => `<line x1="${P.l}" x2="${W - P.r}" y1="${f.y(t)}" y2="${f.y(t)}" class="${t === 0 ? "zero" : "grid"}"/><text x="${P.l - 8}" y="${f.y(t) + 4}" text-anchor="end">${short(t, unit)}</text>`).join("");
    const xs = [0, 6, 12, 18, 24, 30, months - 1].map((m) => `<text x="${f.x(m)}" y="${H - 10}" text-anchor="middle">${m + 1}</text>`).join("");
    return g + xs + `<text x="${P.l - 8}" y="${H - 10}" text-anchor="end" class="axis-label">maand</text>`;
  }
  const marker = (f, m) => `<line x1="${f.x(m)}" x2="${f.x(m)}" y1="${P.t}" y2="${H - P.b}" class="now"/>`;

  // ------------------------------------------------------------------ data selection
  const sc = () => data.scenarios[state.sc];
  const caseKeys = () => (state.cs === "alle" ? Object.keys(sc().cases) : [state.cs]);
  const rowsOf = (key) => (key === "total" ? sc().total : sc().cases[key].rows);
  const series = () => (state.cs === "alle" ? ["total", ...caseKeys()] : [state.cs]);

  // ------------------------------------------------------------------ charts
  function drawCum() {
    size(760, 280);
    const months = data.horizonMonths;
    const keys = series();
    const all = keys.flatMap((k) => rowsOf(k).map((r) => r.cum));
    const ticks = niceTicks(Math.min(0, ...all), Math.max(0, ...all));
    const f = frame(ticks[0], ticks.at(-1), months);
    const lines = keys.map((k) => {
      const pts = rowsOf(k).map((r) => `${f.x(r.m).toFixed(1)},${f.y(r.cum).toFixed(1)}`).join(" ");
      return `<polyline points="${pts}" fill="none" stroke="${COLORS[k]}" stroke-width="${k === "total" ? 3.5 : 2}" ${k === "total" ? "" : 'stroke-dasharray="0"'} />`;
    }).join("");
    const be = keys.map((k) => {
      const m = k === "total" ? sc().breakEven : sc().cases[k].breakEven;
      return m === null ? "" : `<circle cx="${f.x(m)}" cy="${f.y(0)}" r="5" fill="${COLORS[k]}"/>`;
    }).join("");
    const golive = caseKeys().map((k) => `<line x1="${f.x(sc().cases[k].goLive)}" x2="${f.x(sc().cases[k].goLive)}" y1="${H - P.b}" y2="${H - P.b - 8}" stroke="${COLORS[k]}" stroke-width="3"/>`).join("");
    $("chart-cum").innerHTML = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulatief netto resultaat per maand">${axes(f, ticks, months, "€")}${lines}${be}${golive}${marker(f, state.month - 1)}</svg>`;
    $("legend-cum").innerHTML = keys.map((k) => `<span><i style="background:${COLORS[k]}"></i>${k === "total" ? "Alle cases samen" : esc(sc().cases[k].label)}</span>`).join("") + '<span><i class="dot"></i>terugverdiend (break-even)</span><span><i class="tick"></i>go-live</span>';
  }

  function drawStacked(el, value, unit, aria, negative) {
    size(480, 300);
    const months = data.horizonMonths;
    const keys = caseKeys();
    const pos = Array.from({ length: months }, (_, m) => keys.reduce((a, k) => a + value(rowsOf(k)[m]).pos, 0));
    const neg = Array.from({ length: months }, (_, m) => keys.reduce((a, k) => a + (negative ? value(rowsOf(k)[m]).neg : 0), 0));
    const ticks = niceTicks(negative ? -Math.max(...neg) : 0, Math.max(...pos));
    const f = frame(ticks[0], ticks.at(-1), months);
    const bw = ((W - P.l - P.r) / months) * 0.72;
    let bars = "";
    for (let m = 0; m < months; m++) {
      let up = 0;
      let down = 0;
      for (const k of keys) {
        const v = value(rowsOf(k)[m]);
        if (v.pos > 0) { bars += `<rect x="${(f.x(m) - bw / 2).toFixed(1)}" y="${f.y(up + v.pos).toFixed(1)}" width="${bw.toFixed(1)}" height="${(f.y(up) - f.y(up + v.pos)).toFixed(1)}" fill="${COLORS[k]}"/>`; up += v.pos; }
        if (negative && v.neg > 0) { bars += `<rect x="${(f.x(m) - bw / 2).toFixed(1)}" y="${f.y(-down).toFixed(1)}" width="${bw.toFixed(1)}" height="${(f.y(-down - v.neg) - f.y(-down)).toFixed(1)}" fill="${COLORS[k]}" opacity=".35"/>`; down += v.neg; }
      }
    }
    el.innerHTML = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${aria}">${axes(f, ticks, months, unit)}${bars}${marker(f, state.month - 1)}</svg>`;
  }

  // ------------------------------------------------------------------ tiles and tables
  function tiles() {
    const i = state.month - 1;
    const keys = caseKeys();
    const sum = (k) => keys.reduce((a, c) => a + rowsOf(c)[i][k], 0);
    const cum = sum("cum");
    const invested = keys.reduce((a, c) => a + rowsOf(c).slice(0, i + 1).reduce((b, r) => b + r.invest, 0), 0);
    const benefitSoFar = keys.reduce((a, c) => a + rowsOf(c).slice(0, i + 1).reduce((b, r) => b + r.benefit, 0), 0);
    const be = state.cs === "alle" ? sc().breakEven : sc().cases[state.cs].breakEven;
    const work = keys.map((c) => `<li><b>${int(rowsOf(c)[i].cumWork)}</b> ${esc(sc().cases[c].workLabel)}</li>`).join("");
    $("tiles").innerHTML = `
      <div class="tile ${cum < 0 ? "neg" : "pos"}"><span>Netto tot nu</span><b>${eur(cum)}</b><small>${cum < 0 ? "investering nog niet terugverdiend" : "investering terugverdiend"}</small></div>
      <div class="tile"><span>Terugverdiend in</span><b>${be === null ? "—" : `maand ${be + 1}`}</b><small>${be === null ? `niet binnen ${data.horizonMonths} maanden` : "cumulatief boven nul"}</small></div>
      <div class="tile"><span>Uren vrijgekomen</span><b>${int(sum("cumHours"))}</b><small>samen tot maand ${state.month}</small></div>
      <div class="tile"><span>Baten tot nu</span><b>${eur(benefitSoFar)}</b><small>tegenover ${eur(invested)} investering</small></div>
      <div class="tile wide"><span>Vermeden werk tot nu</span><ul>${work}</ul></div>`;
    $("month-label").textContent = state.month;
    $("vs-month").textContent = state.month;
  }

  function vsTable() {
    const i = state.month - 1;
    const rows = caseKeys().map((k) => {
      const c = sc().cases[k];
      const r = c.rows[i];
      const live = i >= c.goLive;
      return `<tr><th scope="row">${esc(c.label)}</th><td class="was">alles manueel</td><td class="arrow" aria-hidden="true">→</td><td class="now">${live ? `${Math.round(r.adoption * 100)}% van het volle effect` : `nog niet live (go-live maand ${c.goLive + 1})`}</td><td>${int((c.fullYear.hours / 12) * r.adoption)} u/maand vrij</td><td>${int((c.fullYear.work / 12) * r.adoption)} ${esc(c.workLabel)}/maand</td></tr>`;
    }).join("");
    $("vs-table").innerHTML = `<thead><tr><th scope="col">Case</th><th scope="col">Vandaag</th><th aria-hidden="true"></th><th scope="col">Na ${state.month} maanden</th><th scope="col">Tijd</th><th scope="col">Werk</th></tr></thead><tbody>${rows}</tbody>`;
  }

  function caseTable() {
    const rows = Object.entries(sc().cases).map(([, c]) => `<tr><th scope="row">${esc(c.label)}</th><td>maand ${c.goLive + 1}</td><td>${eur(c.oneOff)}</td><td>${eur(c.fullYear.benefit)}</td><td>${eur(c.fullYear.run)}</td><td>${c.breakEven === null ? `niet binnen ${data.horizonMonths} mnd` : `maand ${c.breakEven + 1}`}</td><td class="${c.rows.at(-1).cum < 0 ? "neg" : ""}">${eur(c.rows.at(-1).cum)}</td></tr>`).join("");
    $("case-table").innerHTML = `<caption class="sr-only">Per case, scenario ${state.sc}</caption><thead><tr><th scope="col">Case</th><th scope="col">Go-live</th><th scope="col">Investering</th><th scope="col">Baten/jaar bij vol gebruik</th><th scope="col">Lopende kost/jaar</th><th scope="col">Terugverdiend</th><th scope="col">Na ${data.horizonMonths} maanden</th></tr></thead><tbody>${rows}</tbody>`;
  }

  function render() {
    $("sc-explain").textContent = SCENARIO_TEXT[state.sc];
    tiles();
    drawCum();
    drawStacked($("chart-hours"), (r) => ({ pos: r.hours }), "u", "Vrijgekomen uren per maand, per case");
    drawStacked($("chart-money"), (r) => ({ pos: r.benefit, neg: r.invest + r.run }), "€", "Baten en kosten per maand", true);
    vsTable();
    caseTable();
  }

  // ------------------------------------------------------------------ controls
  function tabs(id, attr, key) {
    $(id).querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
      $(id).querySelectorAll("button").forEach((x) => { x.classList.add("ghost"); x.setAttribute("aria-selected", "false"); });
      b.classList.remove("ghost"); b.setAttribute("aria-selected", "true");
      state[key] = b.dataset[attr];
      render();
    }));
  }
  let timer = 0;
  function play() {
    clearInterval(timer);
    if (reduced) { state.month = data.horizonMonths; $("month").value = state.month; render(); return; }
    state.month = 1;
    timer = setInterval(() => {
      $("month").value = state.month;
      render();
      if (state.month >= data.horizonMonths) clearInterval(timer);
      state.month += 1;
    }, 140);
  }

  fetch("../data/benefits.json").then((r) => r.json()).then((d) => {
    data = d;
    $("month").max = d.horizonMonths;
    tabs("sc-tabs", "sc", "sc");
    tabs("case-tabs", "case", "cs");
    $("month").addEventListener("input", (e) => { clearInterval(timer); state.month = Number(e.target.value); render(); });
    $("play").addEventListener("click", play);
    render();
  }).catch(() => { $("tiles").innerHTML = '<p class="err">De gegevens konden niet laden. De berekening staat in src/benefits.mjs op GitHub.</p>'; });
})();
